from typing import List


class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFFSET = 1800
        SIZE = 3601
        FULL = (1 << SIZE) - 1

        # Max |alternating sum|: at most 75 positive picks of value <= 12
        if abs(k) > 900:
            return -1

        OVER = limit + 1  # sentinel: product exceeded the limit

        def cap(p, n):
            # new product after multiplying state product p by n
            if n == 0 or p == 0:
                return 0
            if p == OVER:
                return OVER
            v = p * n
            return v if v <= limit else OVER

        # dp[(parity, prod)] = bitmask of achievable alternating sums (bit s + OFFSET)
        dp = {}

        for num in nums:
            add = {}
            for (par, prod), mask in dp.items():
                if par == 0:
                    nm = (mask << num) & FULL
                else:
                    nm = mask >> num
                if nm == 0:
                    continue
                key = (1 - par, cap(prod, num))
                cur = add.get(key)
                add[key] = nm if cur is None else (cur | nm)

            # seed the singleton subsequence [num]
            key = (1, cap(1, num))
            bit = 1 << (num + OFFSET)
            cur = add.get(key)
            add[key] = bit if cur is None else (cur | bit)

            for key, m in add.items():
                cur = dp.get(key)
                dp[key] = m if cur is None else (cur | m)

        target = 1 << (k + OFFSET)
        best = -1
        for (par, prod), mask in dp.items():
            if prod != OVER and (mask & target):
                if prod > best:
                    best = prod
        return best

import sys
from heapq import nsmallest, nlargest
from operator import sub


def main():
    data = sys.stdin.buffer.read().split()
    T = int(data[0])
    pos = 1
    INF = 1 << 60

    # all simple paths s -> t in the 4-node graph {0,1,2 = labels, 3 = W}
    SH = {}
    for s in range(3):
        for t in range(3):
            if s != t:
                r = 3 - s - t
                SH[(s, t)] = (((s, t),),
                              ((s, r), (r, t)),
                              ((s, 3), (3, t)),
                              ((s, r), (r, 3), (3, t)),
                              ((s, 3), (3, r), (r, t)))

    out = []
    for _ in range(T):
        N = int(data[pos]); K = int(data[pos + 1]); pos += 2
        e = pos + 3 * N
        ch = data[pos:e]; pos = e
        X = list(map(int, ch[0::3]))
        Y = list(map(int, ch[1::3]))
        Z = list(map(int, ch[2::3]))
        mm = list(map(max, X, Y, Z))
        K2 = K + K
        order = sorted(range(N), key=mm.__getitem__, reverse=True)
        sel = order[:K2]
        M = sum(map(mm.__getitem__, sel))
        lab = [0 if v == x else (1 if v == y else 2) for v, x, y in zip(mm, X, Y)]
        g = ([], [], [])
        for i in sel:
            g[lab[i]].append(i)
        c0 = len(g[0]); c1 = len(g[1]); c2 = len(g[2])
        if not ((c0 | c1 | c2) & 1):
            out.append(M)
            continue
        cnt = (c0, c1, c2)
        odd = [u for u in range(3) if cnt[u] & 1]
        p = odd[0]; q = odd[1]; r = 3 - p - q
        V = (X, Y, Z)
        dif = (list(map(sub, mm, X)), list(map(sub, mm, Y)), list(map(sub, mm, Z)))
        uns = order[K2:]

        # L[group][type] = up to 2 cheapest (cost, cake_id)
        L = [[(), (), (), ()] for _ in range(4)]
        for u in range(3):
            gu = g[u]
            if not gu:
                continue
            for b in range(3):
                if b == u:
                    continue
                db = dif[b]
                L[u][b] = tuple((db[i], i) for i in nsmallest(2, gu, key=db.__getitem__))
            L[u][3] = tuple((mm[i], i) for i in nsmallest(2, gu, key=mm.__getitem__))
        if uns:
            for v in range(3):
                Vv = V[v]
                L[3][v] = tuple((-Vv[i], i) for i in nlargest(2, uns, key=Vv.__getitem__))

        C1 = [[INF] * 4 for _ in range(4)]
        C2 = [[[INF] * 4 for _ in range(4)] for _ in range(4)]
        for gr in range(4):
            Lg = L[gr]
            C1g = C1[gr]
            C2g = C2[gr]
            for b in range(4):
                Lb = Lg[b]
                if not Lb:
                    continue
                C1g[b] = Lb[0][0]
                for b2 in range(b, 4):
                    Lb2 = Lg[b2]
                    if not Lb2:
                        continue
                    bst = INF
                    for ca, ia in Lb:
                        for cb, ib in Lb2:
                            if ia != ib:
                                sm = ca + cb
                                if sm < bst:
                                    bst = sm
                    C2g[b][b2] = bst
                    C2g[b2][b] = bst

        best = INF
        # divergence (+1,-1,0) and (-1,+1,0): a single simple path
        for st in ((p, q), (q, p)):
            for sh in SH[st]:
                tot = 0
                for a, b in sh:
                    tot += C1[a][b]
                if tot < best:
                    best = tot
        # divergence (+1,+1,-2) and (-1,-1,+2): two simple paths, cakes distinct
        for a1, a2 in (((p, r), (q, r)), ((r, p), (r, q))):
            l1 = [sh for sh in SH[a1] if all(C1[a][b] < INF for a, b in sh)]
            if not l1:
                continue
            l2 = [sh for sh in SH[a2] if all(C1[a][b] < INF for a, b in sh)]
            if not l2:
                continue
            for sh1 in l1:
                for sh2 in l2:
                    d0 = []; d1 = []; d2 = []; d3 = []
                    dem = (d0, d1, d2, d3)
                    for a, b in sh1:
                        dem[a].append(b)
                    for a, b in sh2:
                        dem[a].append(b)
                    tot = 0
                    for gr in range(4):
                        d = dem[gr]
                        n = len(d)
                        if n == 1:
                            tot += C1[gr][d[0]]
                        elif n == 2:
                            tot += C2[gr][d[0]][d[1]]
                    if tot < best:
                        best = tot
        out.append(M - best)

    sys.stdout.write('\n'.join(map(str, out)) + '\n')


main()

from typing import List


class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # d(x) = floor(log4 x) + 1 for x >= 1
        # f(n) = sum_{x=1}^{n} d(x)
        # pre[b] = f(4^b - 1) = sum_{j=0}^{b-1} (j+1) * (4^{j+1} - 4^j)
        MAXB = 17
        pows = [1] * (MAXB + 1)
        for k in range(1, MAXB + 1):
            pows[k] = pows[k - 1] * 4
        pre = [0] * (MAXB + 1)
        for b in range(1, MAXB + 1):
            pre[b] = pre[b - 1] + b * (pows[b] - pows[b - 1])

        def f(n: int) -> int:
            if n <= 0:
                return 0
            b = (n.bit_length() - 1) >> 1  # 4^b <= n < 4^(b+1)
            return pre[b] + (b + 1) * (n - pows[b] + 1)

        total = 0
        for l, r in queries:
            S = f(r) - f(l - 1)
            total += (S + 1) >> 1
        return total


if __name__ == "__main__":
    sol = Solution()
    # provided examples
    assert sol.minOperations([[1, 2], [2, 4]]) == 3
    assert sol.minOperations([[2, 6]]) == 4

    # brute force check: greedy pair-the-two-largest simulation
    import heapq

    def d(x):
        c = 0
        while x > 0:
            x //= 4
            c += 1
        return c

    def brute(l, r):
        h = [-d(x) for x in range(l, r + 1)]
        heapq.heapify(h)
        ops = 0
        while True:
            a = -heapq.heappop(h)
            if a == 0:
                break
            b = -heapq.heappop(h) if h else 0
            ops += 1
            heapq.heappush(h, -(a - 1))
            heapq.heappush(h, -max(b - 1, 0))
        return ops

    for l in range(1, 41):
        for r in range(l + 1, 41):
            assert sol.minOperations([[l, r]]) == brute(l, r), (l, r)
    print("all tests passed")

import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0]); ne = int(data[1])
    deg = [0]*(n+2)
    U = [0]*ne; V = [0]*ne
    ptr = 2
    for i in range(ne):
        u = int(data[ptr]); v = int(data[ptr+1]); ptr += 2
        U[i] = u; V[i] = v
        deg[u] += 1; deg[v] += 1
    head = [0]*(n+2)
    s = 0
    for v in range(1, n+1):
        head[v] = s
        s += deg[v]
    head[n+1] = s
    pos = head[:]
    adj = [0]*(2*ne)
    for i in range(ne):
        u = U[i]; v = V[i]
        adj[pos[u]] = v; pos[u] += 1
        adj[pos[v]] = u; pos[v] += 1

    color = [-1]*(n+1)
    sumxy = 0
    K = 0   # number of odd-size components
    I = 0   # number of isolated vertices
    for s0 in range(1, n+1):
        if color[s0] != -1:
            continue
        color[s0] = 0
        c0 = 1; c1 = 0
        stack = [s0]
        while stack:
            u = stack.pop()
            cu = color[u]
            nc = cu ^ 1
            for k in range(head[u], head[u]+deg[u]):
                w = adj[k]
                if color[w] == -1:
                    color[w] = nc
                    if nc == 0:
                        c0 += 1
                    else:
                        c1 += 1
                    stack.append(w)
        x = c0; y = c1
        sumxy += x*y
        if (x + y) & 1:
            K += 1
        if x + y == 1:
            I += 1

    if n & 1:
        # a*b is always even  =>  total moves == ne (mod 2)
        print("Aoki" if (ne & 1) else "Takahashi")
        return

    phi = sumxy - ne          # currently addable internal edges
    m = K // 2
    if I == 2*m:
        win = ((phi + m) & 1) == 1
    elif I >= 2*m - 2:
        win = True
    else:
        win = (ne & 1) == 1
    print("Aoki" if win else "Takahashi")


