# development helper: python prog.py --selftest [Nmax]
# brute-force minimax over abstract states, compared with the formula
# ------------------------------------------------------------------
def _formula(state):
    N = sum(x+y for x, y, e in state)
    M = sum(e for x, y, e in state)
    if N & 1:
        return (M & 1) == 1
    sumxy = sum(x*y for x, y, e in state)
    K = sum(1 for x, y, e in state if (x+y) & 1)
    I = sum(1 for x, y, e in state if x+y == 1)
    phi = sumxy - M
    m = K // 2
    if I == 2*m:
        return ((phi + m) & 1) == 1
    if I >= 2*m - 2:
        return True
    return (M & 1) == 1


def _selftest(argv):
    sys.setrecursionlimit(100000)
    memo = {}

    def moves(state):
        res = set()
        L = list(state)
        k = len(L)
        for i in range(k):
            x, y, e = L[i]
            if e < x*y:
                nl = L[:i] + [(x, y, e+1)] + L[i+1:]
                res.add(tuple(sorted(nl)))
        for i in range(k):
            for j in range(i+1, k):
                x1, y1, e1 = L[i]
                x2, y2, e2 = L[j]
                rest = [L[t] for t in range(k) if t != i and t != j]
                cands = []
                if (x1 >= 1 and y2 >= 1) or (y1 >= 1 and x2 >= 1):
                    cands.append((x1+x2, y1+y2))
                if (x1 >= 1 and x2 >= 1) or (y1 >= 1 and y2 >= 1):
                    cands.append((x1+y2, y1+x2))
                for (a, b) in cands:
                    if a < b:
                        a, b = b, a
                    res.add(tuple(sorted(rest + [(a, b, e1+e2+1)])))
        return res

    def win(state):
        r = memo.get(state)
        if r is not None:
            return r
        r = False
        for ns in moves(state):
            if not win(ns):
                r = True
                break
        memo[state] = r
        return r

    def gen(N):
        comps = []
        for size in range(1, N+1):
            for y in range(0, size//2 + 1):
                x = size - y
                if y == 0:
                    if size == 1:
                        comps.append((1, 0, 0))
                else:
                    for e in range(x+y-1, x*y+1):
                        comps.append((x, y, e))
        comps.sort()
        out = []

        def rec(idx, remaining, cur):
            if remaining == 0:
                out.append(tuple(sorted(cur)))
                return
            for t in range(idx, len(comps)):
                c = comps[t]
                if c[0] + c[1] <= remaining:
                    rec(t, remaining - (c[0]+c[1]), cur + [c])
        rec(0, N, [])
        return out

    nmax = int(argv[2]) if len(argv) > 2 else 8
    bad = 0
    for N in range(1, nmax+1):
        for st in gen(N):
            if win(st) != _formula(st):
                bad += 1
                print("MISMATCH", st, "brute:", win(st), "formula:", _formula(st))
                if bad > 20:
                    return
        print("N =", N, "ok")
    print("all ok" if bad == 0 else "mismatches: %d" % bad)


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "--selftest":
        _selftest(sys.argv)
    else:
        main()

import sys

# Module-level memo: non-tight DP states depend only on (remaining free digits,
# started flag, running digit sum, running digit product), never on the bound N.
# Caching it globally makes repeated calls (many test cases) essentially free.
_MEMO = {}


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        memo = _MEMO

        def dfs(rem: int, started: bool, s: int, p: int) -> int:
            """Number of ways to fill `rem` completely free digits (0..9 each)
            so that the whole number is beautiful, given the prefix already has
            digit-sum s and digit-product p (`started` False => prefix is all
            leading zeros, i.e. no significant digit yet)."""
            if rem == 0:
                # 'started' False here means the number is 0 -> not counted.
                return 1 if (started and p % s == 0) else 0
            if started and p == 0:
                # product already 0 -> 0 % (positive sum) == 0 for every suffix
                return 10 ** rem
            key = (rem, started, s, p)
            v = memo.get(key)
            if v is not None:
                return v
            if not started:
                # a 0 here is still a leading zero
                total = dfs(rem - 1, False, 0, 1)
                for d in range(1, 10):
                    total += dfs(rem - 1, True, d, d)
            else:
                total = dfs(rem - 1, True, s, 0)  # digit 0 -> product becomes 0
                for d in range(1, 10):
                    total += dfs(rem - 1, True, s + d, p * d)
            memo[key] = total
            return total

        def count(N: int) -> int:
            """Beautiful numbers in [1, N]."""
            if N <= 0:
                return 0
            ds = list(map(int, str(N)))
            n = len(ds)
            total = 0
            s = 0
            p = 1
            started = False
            for i in range(n):
                dig = ds[i]
                rem = n - i - 1
                for d in range(dig):
                    if not started and d == 0:
                        total += dfs(rem, False, 0, 1)
                    else:
                        total += dfs(rem, True, s + d, p * d)
                # follow the tight branch with digit == dig
                if started or dig != 0:
                    started = True
                    s += dig
                    p *= dig
            # N itself (N >= 1 so `started` is True here)
            if started and p % s == 0:
                total += 1
            return total

        return count(r) - count(l - 1)

import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0]); M = int(data[1]); K = int(data[2])
    edges = []
    ptr = 3
    for _ in range(M):
        u = int(data[ptr]); v = int(data[ptr + 1]); ptr += 2
        edges.append((u, v))

    INF = K + 1          # any cut using an INF arc already exceeds K
    limit = K + 1        # early stop for max-flow

    def min_tight(d):
        """min number of 'tight' edges over labelings p:V->{0..d}, p(1)=0, p(N)=d,
           p(v)-p(u) <= 1 for every edge.  Value capped at K+1."""
        if d == 0:
            return 0
        S = 0
        T = 1
        inter = N - 2
        nnodes = 2 + (inter if inter > 0 else 0) * d
        to = []
        cap = []
        head = [[] for _ in range(nnodes)]

        def add(a, b, c):
            head[a].append(len(to)); to.append(b); cap.append(c)
            head[b].append(len(to)); to.append(a); cap.append(0)

        def nid(i, k):
            # y_{i,k} = [p_i >= k]; y=1 <=> source side
            if i == 1:
                return T          # p_1 = 0  => all y_{1,k} = 0 (sink side)
            if i == N:
                return S          # p_N = d  => all y_{N,k} = 1 (source side)
            return 2 + (i - 2) * d + (k - 1)

        # monotonicity y_{i,k+1} <= y_{i,k}
        for i in range(2, N):
            for k in range(1, d):
                a = nid(i, k + 1); b = nid(i, k)
                if a != b:
                    add(a, b, INF)

        # g(x) = 1*max(0,x) + INF*max(0,x-1),  x = p_v - p_u
        for (u, v) in edges:
            for k in range(1, d + 1):
                a = nid(v, k); b = nid(u, k)
                if a != b:
                    add(a, b, 1)
            for k in range(2, d + 1):
                a = nid(v, k); b = nid(u, k - 1)
                if a != b:
                    add(a, b, INF)

        # ---- Dinic with flow limit ----
        flow = 0
        while flow < limit:
            level = [-1] * nnodes
            level[S] = 0
            q = deque([S])
            while q:
                x = q.popleft()
                for eid in head[x]:
                    if cap[eid] > 0:
                        y = to[eid]
                        if level[y] < 0:
                            level[y] = level[x] + 1
                            q.append(y)
            if level[T] < 0:
                break
            it = [0] * nnodes
            while flow < limit:
                stack = [S]
                path = []
                found = False
                while stack:
                    x = stack[-1]
                    if x == T:
                        found = True
                        break
                    hx = head[x]
                    lx = level[x] + 1
                    while it[x] < len(hx):
                        eid = hx[it[x]]
                        if cap[eid] > 0 and level[to[eid]] == lx:
                            break
                        it[x] += 1
                    if it[x] == len(hx):
                        level[x] = -1
                        stack.pop()
                        if path:
                            path.pop()
                            it[stack[-1]] += 1
                    else:
                        eid = hx[it[x]]
                        path.append(eid)
                        stack.append(to[eid])
                if not found:
                    break
                f = limit - flow
                for eid in path:
                    if cap[eid] < f:
                        f = cap[eid]
                for eid in path:
                    cap[eid] -= f
                    cap[eid ^ 1] += f
                flow += f
        return flow

    ans = 0
    hi = K if K < N - 1 else N - 1
    for d in range(hi, 0, -1):
        if min_tight(d) <= K:
            ans = d
            break
    print(ans)

main()

import sys
from collections import Counter

def main():
    data = sys.stdin.read().split()
    if not data:
        print(1)
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ''
    s = s.strip()
    MOD = 998244353

    m = max(len(s), n, 1) + 2
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (m + 1)
    inv_fact[m] = pow(fact[m], MOD - 2, MOD)
    for i in range(m, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    memo = {}
    ans = 1
    stack = [[]]  # virtual root's children list
    for c in s:
        if c == '(':
            stack.append([])
        elif c == ')':
            ch = stack.pop()
            key = tuple(sorted(ch))
            idx = memo.get(key)
            if idx is None:
                idx = len(memo)
                memo[key] = idx
            f = fact[len(ch)]
            if ch:
                for v in Counter(ch).values():
                    if v > 1:
                        f = f * inv_fact[v] % MOD
            ans = ans * f % MOD
            if not stack:
                stack = [[]]
            stack[-1].append(idx)
        else:
            continue

    top = stack[0] if stack else []
    f = fact[len(top)]
    if top:
        for v in Counter(top).values():
            if v > 1:
                f = f * inv_fact[v] % MOD
    ans = ans * f % MOD

    print(ans % MOD)


