class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        size = n * m
        g = [v for row in grid for v in row]
        # expected next value: after 1 -> 2, after 2 -> 0, after 0 -> 2
        NEXT = [2, 2, 0]
        nxtf = [NEXT[v] for v in g]

        # clockwise order: SE -> SW -> NW -> NE -> SE  ((dr,dc) -> (dc,-dr))
        DIRS = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # ---------- f[d]: longest straight chain starting at cell, direction d ----------
        F = []
        for di, dj in DIRS:
            f = [1] * size
            rows = range(n - 2, -1, -1) if di == 1 else range(1, n)
            for i in rows:
                b = i * m
                nb = (i + di) * m
                if dj == 1:
                    if m > 1:
                        f[b:b + m - 1] = [
                            fn + 1 if gn == e else 1
                            for gn, e, fn in zip(g[nb + 1:nb + m],
                                                 nxtf[b:b + m - 1],
                                                 f[nb + 1:nb + m])
                        ]
                else:
                    if m > 1:
                        f[b + 1:b + m] = [
                            fn + 1 if gn == e else 1
                            for gn, e, fn in zip(g[nb:nb + m - 1],
                                                 nxtf[b + 1:b + m],
                                                 f[nb:nb + m - 1])
                        ]
            F.append(f)

        # ---------- h[d]: longest chain starting at cell, direction d, one CW turn left ----------
        zero_row = [0] * m
        H = []
        for d in range(4):
            di, dj = DIRS[d]
            d2 = (d + 1) % 4
            di2, dj2 = DIRS[d2]
            fp = F[d2]
            h = [1] * size
            rows = range(n - 1, -1, -1) if di == 1 else range(0, n)
            for i in rows:
                b = i * m
                ni = i + di
                mi = i + di2

                # option A: continue in direction d (uses h[d] of neighbour row)
                if 0 <= ni < n:
                    nb = ni * m
                    if dj == 1:
                        if m > 1:
                            A = [
                                x if gn == e else 0
                                for gn, e, x in zip(g[nb + 1:nb + m],
                                                    nxtf[b:b + m - 1],
                                                    h[nb + 1:nb + m])
                            ]
                            A.append(0)
                        else:
                            A = zero_row
                    else:
                        if m > 1:
                            A = [0]
                            A.extend([
                                x if gn == e else 0
                                for gn, e, x in zip(g[nb:nb + m - 1],
                                                    nxtf[b + 1:b + m],
                                                    h[nb:nb + m - 1])
                            ])
                        else:
                            A = zero_row
                else:
                    A = zero_row

                # option B: turn here into d2 (uses f[d2] of neighbour in direction d2)
                if 0 <= mi < n:
                    mb = mi * m
                    if dj2 == 1:
                        if m > 1:
                            B = [
                                x if gn == e else 0
                                for gn, e, x in zip(g[mb + 1:mb + m],
                                                    nxtf[b:b + m - 1],
                                                    fp[mb + 1:mb + m])
                            ]
                            B.append(0)
                        else:
                            B = zero_row
                    else:
                        if m > 1:
                            B = [0]
                            B.extend([
                                x if gn == e else 0
                                for gn, e, x in zip(g[mb:mb + m - 1],
                                                    nxtf[b + 1:b + m],
                                                    fp[mb:mb + m - 1])
                            ])
                        else:
                            B = zero_row
                else:
                    B = zero_row

                h[b:b + m] = [1 + (a if a > c else c) for a, c in zip(A, B)]
            H.append(h)

        ones = [idx for idx in range(size) if g[idx] == 1]
        if not ones:
            return 0
        ans = 0
        for h in H:
            for idx in ones:
                v = h[idx]
                if v > ans:
                    ans = v
        return ans


