# Task E: exhaustive brute force + randomized cross-check + timing (dev only)
# ---------------------------------------------------------------------------
def _brute(grid):
    """Exhaustive enumerator: every start cell with value 1, all 4 diagonal
    directions, sequence 1 then 2,0,2,0..., at most one 90-degree CLOCKWISE
    turn, turn cell counted once."""
    n, m = len(grid), len(grid[0])
    NEXT = {1: 2, 2: 0, 0: 2}
    DIRS = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise cycle
    best = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 1:
                continue
            if best < 1:
                best = 1
            for d in range(4):
                di, dj = DIRS[d]
                # straight run cells starting at (i,j)
                path = [(i, j)]
                ci, cj = i, j
                while True:
                    ni, nj = ci + di, cj + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == NEXT[grid[ci][cj]]:
                        path.append((ni, nj))
                        ci, cj = ni, nj
                    else:
                        break
                if len(path) > best:
                    best = len(path)
                di2, dj2 = DIRS[(d + 1) % 4]
                for p in range(len(path)):
                    ci, cj = path[p]
                    L = p + 1
                    while True:
                        ni, nj = ci + di2, cj + dj2
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == NEXT[grid[ci][cj]]:
                            L += 1
                            ci, cj = ni, nj
                        else:
                            break
                    if L > best:
                        best = L
    return best


