    pos = 0
    n = int(data[pos]); pos += 1
    X = int(data[pos]); pos += 1
    groups = [[], [], []]
    for _ in range(n):
        v = int(data[pos]); a = int(data[pos+1]); c = int(data[pos+2])
        pos += 3
        if c <= X:
            groups[v-1].append((a, c))

