from typing import List


class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def f(t: int) -> int:
            # number of (x,y) with x,y >= 0 and x+y <= t
            if t < 0:
                return 0
            return (t + 1) * (t + 2) // 2

        def sum_of_maxes(arr: List[int], k: int) -> int:
            n = len(arr)
            m = k - 1
            L = [-1] * n   # nearest index to the left with strictly greater value
            R = [n] * n    # nearest index to the right with value >= arr[i]
            stack = []
            for i in range(n):
                v = arr[i]
                while stack and arr[stack[-1]] <= v:
                    j = stack.pop()
                    R[j] = i
                L[i] = stack[-1] if stack else -1
                stack.append(i)
            # remaining entries keep R = n
            total = 0
            for i in range(n):
                a = i - L[i]
                b = R[i] - i
                cnt = f(m) - f(m - a) - f(m - b) + f(m - a - b)
                if cnt:
                    total += arr[i] * cnt
            return total

        return sum_of_maxes(nums, k) - sum_of_maxes([-x for x in nums], k)

class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7

        def T(t):
            return (t * t * t - t) // 6

        S = ((n % MOD) * (n % MOD) % MOD) * (T(m) % MOD) % MOD
        S = (S + ((m % MOD) * (m % MOD) % MOD) * (T(n) % MOD)) % MOD

        N = m * n
        size = max(N, 2)
        fact = [1] * (size + 1)
        for i in range(1, size + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (size + 1)
        inv_fact[size] = pow(fact[size], MOD - 2, MOD)
        for i in range(size, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def nCr(a, b):
            if b < 0 or a < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        return S * nCr(N - 2, k - 2) % MOD

import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    L = list(map(int, data[2::2]))
    R = list(map(int, data[3::2]))
    # safety: ensure lengths
    if len(L) > m:
        L = L[:m]
    if len(R) > m:
        R = R[:m]

    out = sys.stdout.write

    def emit(cost, assignments):
        ops = ['0'] * m
        for idx, o in assignments:
            ops[idx] = o
        out(str(cost) + "\n" + " ".join(ops) + "\n")

    # (1) cost 1
    for i in range(m):
        if L[i] == 1 and R[i] == n:
            emit(1, [(i, '1')])
            return

    # (2) two op1: [1,a] and [b,n] with a+1 >= b
    best_i = -1  # argmax R among L==1
    best_j = -1  # argmin L among R==n
    for i in range(m):
        if L[i] == 1:
            if best_i == -1 or R[i] > R[best_i]:
                best_i = i
        if R[i] == n:
            if best_j == -1 or L[i] < L[best_j]:
                best_j = i
    if best_i != -1 and best_j != -1 and best_i != best_j:
        if R[best_i] + 1 >= L[best_j]:
            emit(2, [(best_i, '1'), (best_j, '1')])
            return

    # (3) containment: op1 on container, op2 on contained
    order = sorted(range(m), key=lambda i: (L[i], -R[i]))
    bestR = -1
    bestIdx = -1
    for idx in order:
        if bestIdx != -1 and R[idx] <= bestR:
            emit(2, [(bestIdx, '1'), (idx, '2')])
            return
        else:
            bestR = R[idx]
            bestIdx = idx

    # (4) disjoint pair: op2 on both
    a = 0  # argmin R
    b = 0  # argmax L
    for i in range(1, m):
        if R[i] < R[a]:
            a = i
        if L[i] > L[b]:
            b = i
    if a != b and L[b] > R[a]:
        emit(2, [(a, '2'), (b, '2')])
        return

    # (5) cost 3
    if m >= 3 and a != b:
        c = -1
        for i in range(m):
            if i != a and i != b:
                c = i
                break
        if c != -1:
            emit(3, [(a, '2'), (b, '2'), (c, '1')])
            return

    out("-1\n")

