import sys

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1]); A = int(data[2]); B = int(data[3])

    full = (1 << B) - 1
    shift = A - 1
    W = (1 << (B - A + 1)) - 1

    if A == B:
        # step is a pure rotate-left by 1 of an A-bit word
        def advance_free(mask, k):
            if mask == 0 or k <= 0:
                return mask
            r = k % A
            if r == 0:
                return mask
            return ((mask << r) | (mask >> (A - r))) & full
    else:
        cache = {}  # mask -> (chain_list, index)  with chain_list[index] == mask

        def advance_free(mask, k):
            while k > 0:
                if mask == 0:
                    return 0
                if mask == full:
                    return full          # full is a fixed point when A < B
                ent = cache.get(mask)
                if ent is None:
                    seq = [mask]
                    local = {mask: 0}
                    m = mask
                    while True:
                        b = 1 if ((m >> shift) & W) else 0
                        m = ((m << 1) | b) & full
                        seq.append(m)
                        if m == 0 or m == full or (m in cache) or (m in local):
                            break
                        local[m] = len(seq) - 1
                    last = seq[-1]
                    if last in local:
                        # cycle inside this chain (should not happen for A<B, safety path)
                        start = local[last]
                        period = (len(seq) - 1) - start
                        if k < start:
                            return seq[k]
                        return seq[start + ((k - start) % period)]
                    for i in range(len(seq) - 1):
                        mm = seq[i]
                        if mm not in cache:
                            cache[mm] = (seq, i)
                    ent = cache[mask]
                lst, idx = ent
                avail = len(lst) - 1 - idx
                if k <= avail:
                    return lst[idx + k]
                k -= avail
                mask = lst[-1]
            return mask

    def advance_bad(mask, length):
        if length >= B:
            return 0
        return (mask << length) & full

    x = 1
    mask = 1
    ok = True

    pos = 4
    for _ in range(M):
        L = int(data[pos]); R = int(data[pos + 1]); pos += 2
        if not ok:
            continue
        free_len = L - 1 - x
        if free_len > 0:
            mask = advance_free(mask, free_len)
            if mask == 0:
                ok = False
                x = R
                continue
        x = L - 1
        mask = advance_bad(mask, R - L + 1)
        x = R
        if mask == 0:
            ok = False
            continue

    if not ok:
        sys.stdout.write("No\n")
        return

    rem = N - x
    if rem > 0:
        mask = advance_free(mask, rem)

    sys.stdout.write("Yes\n" if (mask & 1) else "No\n")

main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    A = [int(x) - 1 for x in data[2:2 + n]]
    MOD = 998244353

    # ---- functional graph cycle detection (iterative, 3-state coloring) ----
    color = [0] * n          # 0 unvisited, 1 on current path, 2 finished
    on_cycle = [False] * n
    cycles = []
    for s in range(n):
        if color[s]:
            continue
        path = []
        v = s
        while color[v] == 0:
            color[v] = 1
            path.append(v)
            v = A[v]
        if color[v] == 1:
            # new cycle found, starting at v
            cyc = []
            u = v
            while True:
                cyc.append(u)
                on_cycle[u] = True
                u = A[u]
                if u == v:
                    break
            cycles.append(cyc)
        for u in path:
            color[u] = 2

    # ---- children lists (only non-cycle nodes hang as children) ----
    children = [[] for _ in range(n)]
    for i in range(n):
        if not on_cycle[i]:
            children[A[i]].append(i)

    # ---- bottom-up order (iterative DFS from cycle nodes' children) ----
    order = []
    stack = []
    for cyc in cycles:
        for u in cyc:
            ch = children[u]
            if ch:
                stack.extend(ch)
    while stack:
        v = stack.pop()
        order.append(v)
        ch = children[v]
        if ch:
            stack.extend(ch)

    try:
        import numpy as np
    except Exception:
        np = None

    ans = 1

    if np is not None:
        base = np.arange(1, m + 1, dtype=np.int64)   # cumsum of all-ones
        acc = [None] * n                             # None means "all ones"
        for v in reversed(order):
            a = acc[v]
            if a is None:
                p = base
            else:
                p = np.cumsum(a) % MOD
                acc[v] = None
            par = A[v]
            b = acc[par]
            if b is None:
                acc[par] = p
            else:
                acc[par] = b * p % MOD
        for cyc in cycles:
            g = None
            for u in cyc:
                au = acc[u]
                if au is not None:
                    g = au if g is None else g * au % MOD
            if g is None:
                comp = m % MOD
            else:
                comp = int(g.sum() % MOD)
            ans = ans * comp % MOD
    else:
        from itertools import accumulate
        base = list(range(1, m + 1))
        acc = [None] * n
        for v in reversed(order):
            a = acc[v]
            if a is None:
                p = base
            else:
                p = [x % MOD for x in accumulate(a)]
                acc[v] = None
            par = A[v]
            b = acc[par]
            if b is None:
                acc[par] = p
            else:
                acc[par] = [x * y % MOD for x, y in zip(b, p)]
        for cyc in cycles:
            g = None
            for u in cyc:
                au = acc[u]
                if au is not None:
                    g = au if g is None else [x * y % MOD for x, y in zip(g, au)]
            if g is None:
                comp = m % MOD
            else:
                comp = sum(g) % MOD
            ans = ans * comp % MOD

    sys.stdout.write(str(ans % MOD) + "\n")

main()

MOD = 10**9 + 7


class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        if k < 0 or k > n - 1:
            return 0
        N = n  # need factorials up to n-1
        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (N + 1)
        inv_fact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        comb = fact[n - 1] * inv_fact[k] % MOD * inv_fact[n - 1 - k] % MOD
        return m % MOD * comb % MOD * pow((m - 1) % MOD, n - 1 - k, MOD) % MOD


if __name__ == "__main__":
    s = Solution()
    assert s.countGoodArrays(3, 2, 1) == 4
    assert s.countGoodArrays(4, 2, 2) == 6
    assert s.countGoodArrays(5, 2, 0) == 2

    # brute force validation
    from itertools import product

    def brute(n, m, k):
        c = 0
        for arr in product(range(1, m + 1), repeat=n):
            if sum(1 for i in range(1, n) if arr[i - 1] == arr[i]) == k:
                c += 1
        return c

    for n in range(1, 7):
        for m in range(1, 5):
            for k in range(0, n):
                assert brute(n, m, k) == s.countGoodArrays(n, m, k), (n, m, k)
    print("ok")

